#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    int *data;
    int capacity;
    int head;
    int tail;
    int size;
} Queue;

Queue *queue_create(int capacity) {
    Queue *q = malloc(sizeof(Queue));
    if (!q) return NULL;
    q->data = malloc(sizeof(int) * capacity);
    if (!q->data) { free(q); return NULL; }
    q->capacity = capacity;
    q->head = 0;
    q->tail = 0;
    q->size = 0;
    return q;
}

bool queue_enqueue(Queue *q, int value) {
    if (q->size == q->capacity) return false;
